const employeeJobTitles = [...new Set([...ROLES, 'Salesman', 'Gate Security Officer', 'Security Supervisor', 'Transport Officer'])];

function loadState() {
  // Supabase is the source of truth. Ignore the old browser demo snapshot.
  return { ...structuredClone(emptyState), manufacturing: emptyManufacturing() };
}
function Avatar({ person, small = false }) { return <span className={`avatar ${person?.color || 'green'} ${small ? 'small' : ''}`}>{initials(person?.name)}</span>; }
function Badge({ status }) { const tone = ['Active', 'Paid', 'Approved', 'Present', 'Completed'].includes(status) ? 'positive' : ['Pending', 'Draft', 'Late'].includes(status) ? 'warning' : ['Overdue', 'Rejected', 'Absent', 'Inactive'].includes(status) ? 'negative' : 'neutral'; return <span className={`badge ${tone}`}><i />{status}</span>; }
function Button({ children, variant = 'secondary', className = '', ...props }) { return <button className={`button ${variant} ${className}`} {...props}>{children}</button>; }
function Empty({ title = 'No results found', text = 'Try changing your search or filters.' }) { return <div className="empty"><Search size={26} /><h3>{title}</h3><p>{text}</p></div>; }
function PersonCell({ person, subtitle }) { return <div className="person-cell"><Avatar person={person} /><div><strong>{person?.name || 'Unknown employee'}</strong><span>{subtitle || person?.email}</span></div></div>; }
function Metric({ label, value, icon: Icon, note, accent, mini, onClick }) { return <div className={`metric ${accent ? 'accent' : ''}`}><div className="metric-top"><span>{label}</span><span className="metric-icon"><Icon size={18} /></span></div><div className="metric-value">{value}</div><div className="metric-bottom">{note}{onClick && <button className="icon-button" aria-label={`View ${label}`} onClick={onClick}><ArrowUpRight size={16} /></button>}</div></div>; }
function PageTitle({ eyebrow, title, description, children }) { return <div className="page-title"><div>{eyebrow && <span className="eyebrow">{eyebrow}</span>}<h1>{title}</h1><p>{description}</p></div><div className="title-actions">{children}</div></div>; }
function PanelHeading({ title, subtitle, children }) { return <div className="panel-heading"><div><h2>{title}</h2>{subtitle && <p>{subtitle}</p>}</div>{children}</div>; }

function SalesTeamAssignment({ data, update, officerId }) {
  const unassigned = data.employees.filter(e => e.role === 'Salesman' && e.status === 'Active' && !e.supervisorId && !e.supervisor_id);
  if (!unassigned.length) return null;
  return <section className="panel sales-team-assignment"><PanelHeading title="Assign Salesmen to your team" subtitle="This saves the Sales Officer relationship on the existing HR employee record." />{unassigned.map(e => <div key={e.id}><PersonCell person={e} subtitle={`${e.id} · ${e.department}`} /><Button variant="primary" onClick={() => update(d => ({ ...d, employees: d.employees.map(x => x.id === e.id ? { ...x, supervisorId: officerId } : x) }), `${e.name} assigned to the Sales Officer team`, 'people')}>Assign to my team</Button></div>)}</section>;
}

function DepartmentGate({selected,onSelect,onBack,onSubmit,error,employees=[],onBeginner}) {
  const [username,setUsername]=useState('didula');
  const [password,setPassword]=useState('11111');
  const [role,setRole]=useState('');
  const [employeeId,setEmployeeId]=useState('');
  const DeptIcon=selected?.icon;
  const salesRoles=['Sales Officer','Salesman'];
  const allowedRoles=selected?.id==='sales'?salesRoles:selected?.id==='security'?['Gate Security Officer','Security Supervisor','Transport Officer','Factory Manager']:ROLES;
  const eligible=employees.filter(e=>e.status==='Active'&&allowedRoles.includes(e.role));
  const eligibleRoles=allowedRoles.filter(r=>eligible.some(e=>e.role===r));
  const roleEmployees=eligible.filter(e=>e.role===role);
  useEffect(()=>{
    if(!['manufacturing','sales','security'].includes(selected?.id))return;
    const nextRole=eligibleRoles.includes(role)?role:(eligibleRoles[0]||'');
    setRole(nextRole);
    const nextEmployee=roleEmployees.some(e=>e.id===employeeId)?employeeId:(eligible.find(e=>e.role===nextRole)?.id||'');
    setEmployeeId(nextEmployee);
  },[selected?.id,employees,role]);
  const needsEmployee=['manufacturing','sales','security'].includes(selected?.id);
  const roleLabel=selected?.id==='sales'?'Sales role':selected?.id==='security'?'Security role':'Manufacturing role';
  return <div className="department-gate"><header><a className="gate-brand" href="#departments">orbit<span>.</span></a><span>ERP WORKSPACE</span>{!selected&&<button className="beginner-launch" onClick={onBeginner}><BookOpen size={16}/>Beginner mode</button>}</header>{!selected?<section className="department-picker"><span className="eyebrow">ONE WORKSPACE · DEPARTMENT PORTALS</span><h1>Where would you like to work?</h1><p>Choose a department to open its own dashboard and tools.</p><div className="department-cards">{departmentPortals.map(d=>{const Icon=d.icon;return <button key={d.id} className="department-card" onClick={()=>onSelect(d)}><span><Icon size={23}/></span><strong>{d.name}</strong><p>{d.description}</p><i>Continue to sign in <ArrowRight size={16}/></i></button>;})}</div><small className="gate-footnote">Demo workspace · department access is simulated in this browser.</small></section>:<section className="department-login"><button className="gate-back" onClick={onBack}><ArrowLeft size={16}/>All departments</button><span className="login-dept-icon"><DeptIcon size={25}/></span><span className="eyebrow">{selected.name.toUpperCase()}</span><h1>Sign in to your workspace</h1><p>{selected.description}</p><form onSubmit={e=>{e.preventDefault();onSubmit(selected,username,password,needsEmployee?{role,employeeId}:null);}}><label className="field">Username<input autoComplete="username" value={username} onChange={e=>setUsername(e.target.value)}/></label><label className="field">Password<input type="password" autoComplete="current-password" value={password} onChange={e=>setPassword(e.target.value)}/></label>{needsEmployee&&<><label className="field">{roleLabel}<select aria-label={roleLabel} value={role} onChange={e=>{setRole(e.target.value);setEmployeeId(eligible.find(x=>x.role===e.target.value)?.id||'');}} required disabled={!eligibleRoles.length}><option value="">Select a role</option>{eligibleRoles.map(r=><option key={r} value={r}>{r}</option>)}</select></label><label className="field">Employee<select aria-label="Employee" value={employeeId} onChange={e=>setEmployeeId(e.target.value)} required disabled={!roleEmployees.length}><option value="">Select an employee</option>{roleEmployees.map(e=><option key={e.id} value={e.id}>{e.name}</option>)}</select></label>{!eligibleRoles.length&&<p className="gate-error" role="status">No active employees have this department role yet. Add one in the HR directory first.</p>}</>}{error&&<p className="gate-error" role="alert">{error}</p>}<button className="gate-submit" type="submit" disabled={needsEmployee&&(!role||!employeeId)}>Enter {selected.name} dashboard <ArrowRight size={17}/></button></form><div className="demo-credentials"><strong>Demo sign-in (all roles)</strong><span>Username <b>didula</b></span><span>Password <b>11111</b></span></div><small className="gate-footnote">This demo login is for the frontend preview only.</small></section>}</div>;
}

function Modal({ title, subtitle, onClose, children, wide = false }) {
  const ref = useRef(null);
  useEffect(() => {
    const prev = document.activeElement;
    const el = ref.current;
    el?.querySelector('input, select, textarea, button')?.focus();
    const key = (e) => {
      if (e.key === 'Escape') onClose();
      if (e.key === 'Tab') {
        const items = [...el.querySelectorAll('button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), a[href], [tabindex="0"]')];
        if (!items.length) return;
        if (e.shiftKey && document.activeElement === items[0]) { e.preventDefault(); items.at(-1).focus(); }
        else if (!e.shiftKey && document.activeElement === items.at(-1)) { e.preventDefault(); items[0].focus(); }
      }
    };
    document.addEventListener('keydown', key); document.body.style.overflow = 'hidden';
    return () => { document.removeEventListener('keydown', key); document.body.style.overflow = ''; prev?.focus(); };
  }, []);
  return <div className="modal-backdrop" onMouseDown={e => { if (e.target === e.currentTarget) onClose(); }}><section ref={ref} className={`modal ${wide ? 'wide' : ''}`} role="dialog" aria-modal="true" aria-labelledby="modal-title"><div className="modal-header"><div><h2 id="modal-title">{title}</h2>{subtitle && <p>{subtitle}</p>}</div><button className="icon-button" aria-label="Close dialog" onClick={onClose}><X size={20} /></button></div>{children}</section></div>;
}

export default function App() {
  const [data, setData] = useState(loadState);
  const [backendStatus, setBackendStatus] = useState('Connecting…');
  const backendReady = useRef(false);
  const [activeDepartment, setActiveDepartment] = useState(() => { try { const id=sessionStorage.getItem('orbit-demo-department');return departmentPortals.some(d=>d.id===id)?id:null; } catch { return null; } });
  const activeDept = departmentPortals.find(d=>d.id===activeDepartment);
  const [page, setPage] = useState(() => { let saved=null;try{saved=sessionStorage.getItem('orbit-demo-department')}catch{}const requested=appPageFromHash(location.hash.slice(1));return departmentPortals.find(d=>d.id===saved&&d.group===departmentByPage(requested)?.group&&pages.some(p=>p.id===requested))?requested:(departmentPortals.find(d=>d.id===saved)?.home||'departments'); });
  const [loginDepartment, setLoginDepartment] = useState(null);
  const [loginError, setLoginError] = useState('');
  const [salesActor, setSalesActor] = useState(() => { try { return JSON.parse(sessionStorage.getItem('orbit-demo-sales-actor') || 'null'); } catch { return null; } });
  const [mobileOpen, setMobileOpen] = useState(false);
  const [modal, setModal] = useState(null);
  const [toast, setToast] = useState('');
  const [globalSearch, setGlobalSearch] = useState('');
  const [collapsedGroups, setCollapsedGroups] = useState({ MANUFACTURING: false });
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [manufacturingLaunch, setManufacturingLaunch] = useState(null);
  const [beginner, setBeginner] = useState(null);
  const storageWarned = useRef(false);
  const pendingWorkspaceSave = useRef(null);
  const workspaceSaveTimer = useRef(null);
  useEffect(()=>{const flush=e=>{clearTimeout(workspaceSaveTimer.current);const pending=pendingWorkspaceSave.current;pendingWorkspaceSave.current=null;e.detail.promise=pending?pending():waitForERPSaves();};window.addEventListener('orbit:flush-workspace',flush);return()=>window.removeEventListener('orbit:flush-workspace',flush);},[]);
  useEffect(() => { const refresh = async () => { try { const remote = await fetchERPState(); if(remote.state) { setData(current => ({...migrate(remote.state), manufacturing:{...migrate(remote.state).manufacturing, actor:current.manufacturing.actor}})); backendReady.current=true; setBackendStatus('Database connected'); } } catch { setToast('The workflow saved, but workspace refresh failed. Reload before editing stock.'); } }; window.addEventListener('orbit:workflow-state',refresh); return () => window.removeEventListener('orbit:workflow-state',refresh); }, []);
  useEffect(() => {
    let alive=true;
    (async()=>{try{const remote=await fetchERPState();if(!alive)return;if(remote.state)setData(migrate(remote.state));else await saveERPState(data);backendReady.current=true;setBackendStatus('Database connected');}catch{if(!alive)return;backendReady.current=false;setBackendStatus('Database unavailable');}})();
    return()=>{alive=false;};
  },[]);
  useEffect(() => { try { localStorage.setItem(STORAGE_KEY, JSON.stringify(data)); } catch { if (!storageWarned.current) { setToast('Browser storage is unavailable. Changes will last for this session.'); storageWarned.current = true; } } }, [data]);
  useEffect(()=>{if(!backendReady.current)return;const snapshot=data;const actor=activeDepartment==='sales'&&salesActor?{id:salesActor.employeeId,role:salesActor.role}:activeDepartment==='manufacturing'?{id:data.manufacturing.actor?.employeeId||'',role:data.manufacturing.actor?.role||'Manufacturing'}:activeDepartment==='hr'?{id:'',role:'HR Manager'}:activeDepartment==='finance'?{id:'',role:'Finance Officer'}:null;const save=()=>saveERPState(snapshot,actor).then(()=>setBackendStatus('Database connected')).catch(error=>{backendReady.current=false;setBackendStatus(error.status===409?'Refresh required':'Database unavailable');setToast(error.message||'Database save failed. Refresh before continuing; this change was not synced.');throw error;});pendingWorkspaceSave.current=save;const timer=setTimeout(()=>{pendingWorkspaceSave.current=null;save().catch(()=>{});},350);workspaceSaveTimer.current=timer;return()=>{clearTimeout(timer);pendingWorkspaceSave.current=null;};},[data,activeDepartment,salesActor]);
  useEffect(() => { if (!toast) return; const timer = setTimeout(() => setToast(''), 4500); return () => clearTimeout(timer); }, [toast]);
  useEffect(() => { const shortcut = e => { if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k') { e.preventDefault(); setModal({type:'search'}); } }; window.addEventListener('keydown',shortcut); return () => window.removeEventListener('keydown',shortcut); }, []);
  useEffect(() => { const handler = () => { const next = appPageFromHash(location.hash.slice(1)); if (activeDept && (activeDept.group===departmentByPage(next)?.group || next==='settings')) setPage(next); }; window.addEventListener('hashchange', handler); return () => window.removeEventListener('hashchange', handler); }, [activeDepartment]);
  const navigate = (next) => { if(next==='departments'){leaveDepartment();return;} if(activeDept&&departmentByPage(next)?.group!==activeDept.group&&next!=='settings')return; if(activeDepartment==='manufacturing'&&manufacturingPages.some(p=>p.id===next)&&!(ROLE_PAGES[data.manufacturing.actor.role]||manufacturingPages.map(p=>p.id)).includes(next))return;setPage(next); location.hash = next; setMobileOpen(false); window.scrollTo({ top: 0, behavior: 'smooth' }); };
  const leaveDepartment=()=>{try{sessionStorage.removeItem('orbit-demo-department');sessionStorage.removeItem('orbit-demo-sales-actor')}catch{}setSalesActor(null);setActiveDepartment(null);setLoginDepartment(null);setPage('departments');location.hash='departments';setMobileOpen(false);};
  const enterDepartment=async(department,username,password,identity)=>{if(username.trim().toLowerCase()!=='didula'||password!=='11111'){setLoginError('Demo sign in failed. Use the prefilled demo credentials.');return;}let latest=data;try{const remote=await fetchERPState();if(remote.state)latest=migrate(remote.state);}catch{setBackendStatus('Database unavailable');}if(department.id==='manufacturing'){const employee=latest.employees.find(e=>e.id===identity?.employeeId&&e.status==='Active'&&e.role===identity?.role);if(!employee){setLoginError('Choose an active HR employee assigned to the selected manufacturing role.');return;}latest={...latest,manufacturing:{...latest.manufacturing,actor:{role:identity.role,employeeId:employee.id}}};}if(['sales','security'].includes(department.id)){const employee=latest.employees.find(e=>e.id===identity?.employeeId&&e.status==='Active'&&e.role===identity?.role&&(department.id==='sales'?['Sales Officer','Salesman']:['Gate Security Officer','Security Supervisor','Transport Officer','Factory Manager']).includes(e.role));if(!employee){setLoginError('Choose an active Sales Officer or Salesman from the HR directory.');return;}setSalesActor({role:employee.role,employeeId:employee.id});try{sessionStorage.setItem('orbit-demo-sales-actor',JSON.stringify({role:employee.role,employeeId:employee.id}))}catch{}}setData(latest);try{sessionStorage.setItem('orbit-demo-department',department.id)}catch{}setLoginError('');setActiveDepartment(department.id);const home=department.id==='manufacturing'?(ROLE_HOME[identity?.role]||'factory'):department.home;setPage(home);location.hash=home;setLoginDepartment(null);};
  useEffect(()=>{if(activeDepartment!=='manufacturing')return;const allowed=ROLE_PAGES[data.manufacturing.actor.role]||manufacturingPages.map(p=>p.id);if(manufacturingPages.some(p=>p.id===page)&&!allowed.includes(page)){const home=ROLE_HOME[data.manufacturing.actor.role]||'factory';setPage(home);location.hash=home;}},[activeDepartment,data.manufacturing.actor.role]);
  const notify = (message) => setToast(message);
  const update = (fn, message, kind = 'finance') => { setData(d => { const next = reconcilePayments(fn(d)); return message ? { ...next, activity: [{ id: crypto.randomUUID(), title: message, detail: `Just now · ${data.settings.admin || 'User'}`, kind }, ...next.activity].slice(0, 12) } : next; }); if (message) notify(message); };
  const pending = activeDepartment==='hr' ? data.leaves.filter(x => x.status === 'Pending').length : activeDepartment==='finance' ? data.expenses.filter(x => x.status === 'Pending').length : manufacturingAlerts(data.manufacturing).length;
  const openManufacturing = (destination, launch) => { setModal(null); setManufacturingLaunch(launch); navigate(destination); };
  const startBeginner = () => setBeginner({index:0,context:activeDepartment});
  const moveBeginner = amount => setBeginner(current=>current?{...current,index:Math.max(0,current.index+amount)}:current);
  const props = { data, update, notify, navigate, setModal, openManufacturing, activeDepartment };
  const title = pages.find(p => p.id === page)?.label || 'Settings';
  const group = navGroups.find(g => g.items.some(i => i.id === page))?.title || 'WORKSPACE';
  if(!activeDept)return <><DepartmentGate selected={loginDepartment} onSelect={d=>{setLoginDepartment(d);setLoginError('');}} onBack={()=>{setLoginDepartment(null);setLoginError('');}} onSubmit={enterDepartment} error={loginError} employees={data.employees} onBeginner={startBeginner}/><BeginnerMode active={!!beginner} context={beginner?.context} index={beginner?.index||0} onNext={()=>moveBeginner(1)} onPrevious={()=>moveBeginner(-1)} onJump={index=>setBeginner(current=>current?{...current,index}:current)} onClose={()=>setBeginner(null)}/></>;
  const visibleGroups=navGroups.filter(g=>g.title===activeDept.group).map(g=>g.title==='MANUFACTURING'?{...g,items:g.items.filter(item=>(item.id==='manufacturing-gates'&&!['Cutting Operator','Manufacturing Operator','HR Manager'].includes(data.manufacturing.actor.role))||(ROLE_PAGES[data.manufacturing.actor.role]||manufacturingPages.map(p=>p.id)).includes(item.id))}:g);
  return <div className={`app-shell ${sidebarCollapsed?'sidebar-collapsed':''}`}>
    {mobileOpen && <div className="sidebar-scrim" onClick={() => setMobileOpen(false)} />}
    <aside className={`sidebar ${mobileOpen ? 'open' : ''}`}>
      <a href="#overview" className="brand" onClick={() => navigate('overview')}><span className="brand-symbol"><span /><i /></span>orbit<span className="brand-dot">.</span></a>
      <button className="workspace-switch" aria-label="Workspace settings" onClick={() => navigate('settings')}><span className="workspace-icon"><Building2 size={19} /></span><span><strong>{data.settings.company || 'Workspace'}</strong><small>Business workspace</small></span><ChevronDown size={15} /></button>
      <nav>{visibleGroups.map(g => <div className={`nav-group ${g.title==='MANUFACTURING'?'nav-group-manufacturing':''}`} key={g.title}><button className="nav-group-toggle" aria-label={g.title} title={g.title} aria-expanded={!collapsedGroups[g.title]} onClick={()=>setCollapsedGroups(v=>({...v,[g.title]:!v[g.title]}))}><span className="nav-label">{g.title}</span><ChevronDown size={12}/></button>{!collapsedGroups[g.title]&&g.items.map(({ id, label, icon: Icon }) => <button key={id} aria-label={label} title={label} className={`nav-item ${page === id ? 'active' : ''}`} onClick={() => navigate(id)} aria-current={page === id ? 'page' : undefined}><Icon size={18} /><span>{label}</span>{id === 'leave' && data.leaves.some(l => l.status === 'Pending') && <b>{data.leaves.filter(l => l.status === 'Pending').length}</b>}</button>)}</div>)}</nav>
      <div className="sidebar-bottom"><div className="help-card"><span className="help-spark"><Sparkles size={18} /></span><strong>{activeDept.name} workspace</strong><p>Signed in as didula · Demo access</p></div><button className="nav-item" onClick={leaveDepartment}><ArrowLeft size={18}/><span>Change department</span></button><button aria-label="Settings" title="Settings" className={`nav-item ${page === 'settings' ? 'active' : ''}`} onClick={() => navigate('settings')}><Settings size={18} /><span>Settings</span></button></div>
    </aside>
    <div className="main-shell"><header className="topbar"><div className="breadcrumb"><button className="icon-button desktop-sidebar-toggle" aria-label="Toggle sidebar" onClick={()=>setSidebarCollapsed(v=>!v)}><Menu size={18}/></button><button className="icon-button mobile-menu" aria-label="Open navigation" onClick={() => setMobileOpen(true)}><Menu size={21} /></button><span>{group === 'HUMAN RESOURCES' ? 'Human resources' : group === 'FINANCE' ? 'Finance' : group === 'MANUFACTURING' ? 'Manufacturing' : group === 'FIELD SALES' ? 'Field sales' : 'Workspace'}</span><ChevronRight size={13} /><strong>{title}</strong></div><div className="topbar-actions"><button className="beginner-launch" onClick={startBeginner}><BookOpen size={15}/>Beginner mode</button><button className="global-search-button" onClick={() => setModal({ type: 'search' })}><Search size={16} /><span>Search this department...</span><span className="search-key">⌕</span></button><span className="demo-pill" title={backendStatus}><i />{backendStatus}</span><button className="icon-button notification-button" aria-label={`Notifications, ${pending} pending approvals`} onClick={() => setModal({ type: 'notifications' })}><Bell size={20} />{pending > 0 && <i />}</button><span className="topbar-divider" /><button className="avatar-button" aria-label="Profile settings" onClick={() => navigate('settings')}><Avatar person={{ name: activeDepartment==='manufacturing'?data.employees.find(e=>e.id===data.manufacturing.actor.employeeId)?.name:(data.settings.admin||'Didula'), color: 'peach' }} small /></button></div></header>
      <main key={page}>
        {['gate-dashboard','sales-gates','manufacturing-gates'].includes(page)&&<GatePasses actor={activeDepartment==='manufacturing'?data.manufacturing.actor:salesActor} employees={data.employees}/>}
        {manufacturingPages.some(p=>p.id===page)&&<Manufacturing page={page} launch={manufacturingLaunch} clearLaunch={()=>setManufacturingLaunch(null)} {...props}/>}
        {page==='hr-dashboard'&&<HRDashboard data={data} navigate={navigate}/>}
        {page==='finance-dashboard'&&<FinanceDashboard data={data} navigate={navigate}/>}
        {page==='sales-dashboard'&&activeDepartment==='sales'&&salesActor?.role==='Sales Officer'&&<SalesOfficerDashboard employee={data.employees.find(e=>e.id===salesActor.employeeId)} employees={data.employees} assignment={<SalesTeamAssignment data={data} update={update} officerId={salesActor.employeeId}/>}/>}
        {page==='sales-dashboard'&&activeDepartment==='sales'&&salesActor?.role==='Salesman'&&<SalesmanDashboard employee={data.employees.find(e=>e.id===salesActor.employeeId)} employees={data.employees}/>}
        {page==='overview'&&<div className="manufacturing-entry"><BriefcaseBusiness size={21}/><span><strong>Meet your connected factory.</strong> Materials, cutting, production, and distribution — now part of your workspace.</span><Button variant="primary" onClick={()=>navigate('factory')}>Open manufacturing<ArrowRight size={15}/></Button></div>}
        {page === 'overview' && <Overview {...props} />}
        {page === 'employees' && <Employees {...props} />}
        {page === 'attendance' && <Attendance {...props} />}
        {page === 'leave' && <Leave {...props} />}
        {page === 'payroll' && <Payroll {...props} />}
        {page === 'invoices' && <Invoices {...props} />}
        {page === 'expenses' && <Expenses {...props} />}
        {page === 'accounts' && <Accounts {...props} />}
        {page === 'reports' && <Reports {...props} />}
        {page === 'settings' && <SettingsPage {...props} />}
        <footer><span>© 2026 Orbit. A little more organized.</span><span><span className="status-dot" /> Database-backed · {manufacturingPages.some(p=>p.id===page)?'LKR':'USD / LKR'}</span></footer>
      </main>
    </div>
    {toast && <div className="toast" role="status"><CheckCheck size={19} /><span>{toast}</span><button aria-label="Dismiss notification" onClick={() => setToast('')}><X size={16} /></button></div>}
    {modal && <AppModal key={`${modal.type}-${modal.item?.id || ''}`} modal={modal} onClose={() => setModal(null)} globalSearch={globalSearch} setGlobalSearch={setGlobalSearch} {...props} />}
    <BeginnerMode active={!!beginner} context={beginner?.context} index={beginner?.index||0} onNext={()=>moveBeginner(1)} onPrevious={()=>moveBeginner(-1)} onJump={index=>setBeginner(current=>current?{...current,index}:current)} onClose={()=>setBeginner(null)}/>
  </div>;
}

function Overview({ data: allData, navigate, setModal, notify }) {
  const data = {...allData, invoices: allData.invoices.filter(i=>(i.currency||'USD')==='USD')};
  const [tab, setTab] = useState('All operations');
  const [chartType, setChartType] = useState('6 months');
  const now = new Date();
  const monthKey = date => `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}`;
  const currentMonth = monthKey(now);
  const employees = data.employees.filter(e => e.status !== 'Inactive');
  const present = employees.filter(e => ['Present', 'Late'].includes(data.attendance[e.id]?.status)).length;
  const collected = sum(data.invoices.filter(i => i.status === 'Paid' && (i.paidDate || i.issued || '').startsWith(currentMonth)));
  const paidExpenses = sum(data.expenses.filter(e => e.status === 'Paid' && (e.paidDate || e.date || '').startsWith(currentMonth))) + (data.payroll?.status === 'Paid' && (data.payroll.paidDate || data.payroll.month || currentMonth).startsWith(currentMonth) ? data.payroll.total : 0);
  const awaiting = [...data.leaves.filter(l => l.status === 'Pending').map(l => ({ ...l, kind: 'leave' })), ...data.expenses.filter(e => e.status === 'Pending').map(e => ({ ...e, kind: 'expense' }))].filter(x => tab === 'Human resources' ? x.kind === 'leave' : tab === 'Finance' ? x.kind === 'expense' : true);
  const months = Array.from({length:6},(_,i)=>new Date(now.getFullYear(),now.getMonth()-5+i,1));
  const bars = months.slice(chartType === '3 months' ? -3 : 0).map(date=>{const key=monthKey(date);const income=sum(data.invoices.filter(i=>i.status==='Paid'&&(i.paidDate||i.issued||'').startsWith(key)));const expenses=sum(data.expenses.filter(e=>e.status==='Paid'&&(e.paidDate||e.date||'').startsWith(key)))+(data.payroll?.status==='Paid'&&(data.payroll.paidDate||data.payroll.month||'').startsWith(key)?data.payroll.total:0);return {month:date.toLocaleDateString('en-US',{month:'short'}),income,expenses};});
  const highestBar = Math.max(...bars.flatMap(b => [b.income,b.expenses]));
  const chartMax = highestBar ? Math.ceil(highestBar / 25000) * 25000 : 0;
  const exportOverview = () => { exportCsv('orbit-workspace-overview.csv', [{ employees: employees.length, present, collected, paidExpenses, outstanding: sum(data.invoices.filter(i => ['Pending', 'Overdue'].includes(i.status))), payroll: sum(employees, 'salary') }]); notify('Workspace summary exported'); };
  return <>
    <PageTitle eyebrow="YOUR WORKSPACE, AT A GLANCE" title={`Good morning${data.settings.admin ? `, ${(data.settings.admin || '').split(' ')[0]}` : ''} 👋`} description="Live totals from your connected workspace records."><Button onClick={exportOverview}><Download size={16} />Export report</Button><Button variant="primary" onClick={() => setModal({ type: 'quick' })}><Plus size={17} />Quick add<ChevronDown size={14} /></Button></PageTitle>
    <div className="overview-controls"><div className="tabs">{['All operations', 'Human resources', 'Finance'].map(t => <button key={t} className={tab === t ? 'selected' : ''} onClick={() => setTab(t)}>{t}</button>)}</div><span className="date-label"><CalendarDays size={15} />{now.toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'})}<span className="subtle">· Live database data</span></span></div>
    <div className="metrics-grid">
      {tab !== 'Finance' && <><Metric label="Total employees" value={employees.length.toString()} icon={Users} note={<span>From employee records</span>} onClick={() => navigate('employees')} /><Metric label="At work today" value={present.toString()} icon={BriefcaseBusiness} note={<><span className="trend">{employees.length ? Math.round(present / employees.length * 100) : 0}%</span><span>attendance rate</span></>} mini={2} onClick={() => navigate('attendance')} /></>}
      {tab !== 'Human resources' && <><Metric label="Collected revenue" value={money(collected, true)} icon={TrendingUp} note={<><span className="trend"><ArrowDownLeft size={13} />{data.invoices.filter(i => i.status === 'Paid').length} paid</span><span>This month</span></>} onClick={() => navigate('invoices')} /><Metric accent label="Monthly payroll" value={money(data.payroll?.total || 0, true)} icon={Wallet} note={<><span className="payroll-note"><i />{data.payroll?.status || 'No payroll run'}</span></>} onClick={() => navigate('payroll')} /></>}
      {tab === 'Human resources' && <><Metric label="Leave requests" value={data.leaves.filter(l => l.status === 'Pending').length} icon={CalendarDays} note={<span>Waiting for your approval</span>} onClick={() => navigate('leave')} /><Metric accent label="Monthly payroll" value={money(data.payroll?.total || 0, true)} icon={Wallet} note={<span>{data.payroll?.status || 'No payroll run'}</span>} onClick={() => navigate('payroll')} /></>}
      {tab === 'Finance' && <><Metric label="Outstanding invoices" value={money(sum(data.invoices.filter(i => ['Pending', 'Overdue'].includes(i.status))), true)} icon={FileText} note={<span>Awaiting client payments</span>} onClick={() => navigate('invoices')} /><Metric label="Paid expenses" value={money(paidExpenses, true)} icon={Receipt} note={<span>Paid this month</span>} onClick={() => navigate('expenses')} /></>}
    </div>
    <div className="dashboard-middle">
      <section className="panel cashflow-panel"><PanelHeading title={tab === 'Human resources' ? 'Your team, by department' : 'Cash flow overview'} subtitle={tab === 'Human resources' ? 'Good people. Great things ahead.' : 'A clear view of money coming in and going out.'}>{tab !== 'Human resources' && <select className="compact-select" aria-label="Cash flow period" value={chartType} onChange={e => setChartType(e.target.value)}><option>6 months</option><option>3 months</option></select>}</PanelHeading>
        {tab === 'Human resources' ? <div className="department-bars">{departments.map((dep, i) => <div key={dep}><span>{dep}</span><div><i style={{ width: `${employees.filter(e => e.department === dep).length / Math.max(employees.length, 1) * 100}%`, background: ['#28795a', '#76a78d', '#a7c4b3', '#d3b578', '#a3b4be', '#d8d7b5'][i] }} /></div><b>{employees.filter(e => e.department === dep).length}</b></div>)}</div> : <><div className="chart-meta"><div><span className="chart-total">{money(bars.reduce((n, b) => n + b.income - b.expenses, 0))}</span><span className="subtle">Net cash flow</span></div><div className="chart-legend"><span><i className="income-dot" />Income</span><span><i className="expense-dot" />Expenses</span></div></div><div className="bar-chart" role="img" aria-label={`Cash flow for ${bars.map(b => `${b.month}: income ${money(b.income)}, expenses ${money(b.expenses)}`).join('; ')}`}><div className="y-axis">{[1, 0.75, 0.5, 0.25, 0].map(fraction => money(chartMax * fraction, true)).map(n => <span key={n}>{n}</span>)}</div><div className="plot"><div className="grid-lines">{[0, 1, 2, 3, 4].map(i => <i key={i} />)}</div><div className="bar-groups">{bars.map(b => <div className="bar-group" key={b.month}><div className="bars"><div className="bar income" style={{ height: `${(chartMax ? Math.min(b.income / chartMax * 100, 100) : 0)}%` }} title={`${b.month} income: ${money(b.income)}`} /><div className="bar expense" style={{ height: `${(chartMax ? Math.min(b.expenses / chartMax * 100, 100) : 0)}%` }} title={`${b.month} expenses: ${money(b.expenses)}`} /></div><span>{b.month}</span></div>)}</div></div></div><div className="chart-footer"><span><span className="status-dot" />Database records · October updates with your records</span><button className="text-button" onClick={() => navigate('reports')}>View financial report<ArrowUpRight size={14} /></button></div></>}
      </section>
      <section className="panel approvals-panel"><PanelHeading title="Needs your attention" subtitle="A few things to keep moving."><span className="count-badge">{awaiting.length}</span></PanelHeading><div className="approvals-list">{awaiting.slice(0, 3).map(item => { const person = data.employees.find(e => e.id === item.employeeId); return <button className="approval-item" key={item.id} onClick={() => setModal({ type: item.kind === 'leave' ? 'leave-detail' : 'expense-detail', item })}><span className={`approval-icon ${item.kind === 'leave' ? 'purple' : 'peach'}`}>{item.kind === 'leave' ? <CalendarDays size={18} /> : <Receipt size={18} />}</span><span><strong>{item.kind === 'leave' ? item.type : 'Expense reimbursement'}</strong><small>{person?.name} <span>·</span> {item.kind === 'leave' ? `${daysBetween(item.start, item.end)} day${daysBetween(item.start, item.end) > 1 ? 's' : ''}` : money(item.amount)}</small></span><ChevronRight size={16} /></button>; })}{!awaiting.length && <Empty title="You're all caught up" text="No pending approvals. Nicely done." />}</div><button className="approvals-link" onClick={() => setModal({ type: 'notifications' })}>View all approvals<ArrowRight size={15} /></button><div className="payday-card"><div className="payday-icon"><Wallet size={21} /></div><div><span>UPCOMING PAYDAY</span><strong>{data.payroll?.status || 'No payroll scheduled'}</strong><small>{data.payroll ? `${data.payroll.employees.length} employees ? ${money(data.payroll.total)}` : 'Payroll records will appear here'}</small></div><button aria-label="View payroll" onClick={() => navigate('payroll')}><ArrowUpRight size={18} /></button></div></section>
    </div>
    <div className="dashboard-bottom"><section className="panel team-panel"><PanelHeading title={tab === 'Finance' ? 'Recent invoices' : 'Your people, in focus'} subtitle={tab === 'Finance' ? 'Keep every payment in view.' : 'The people who make it all happen.'}><button className="text-button" onClick={() => navigate(tab === 'Finance' ? 'invoices' : 'employees')}>View all<ArrowRight size={14} /></button></PanelHeading><div className="table-wrap"><table><thead><tr><th>{tab === 'Finance' ? 'CLIENT' : 'EMPLOYEE'}</th><th>{tab === 'Finance' ? 'AMOUNT' : 'DEPARTMENT'}</th><th>STATUS</th><th aria-label="View" /></tr></thead><tbody>{tab === 'Finance' ? data.invoices.slice(0, 4).map(i => <tr key={i.id}><td><strong>{i.client}</strong><small className="cell-subtitle">{i.id}</small></td><td>{money(i.amount)}</td><td><Badge status={i.status} /></td><td><button className="icon-button" aria-label={`View ${i.id}`} onClick={() => setModal({ type: 'invoice-detail', item: i })}><ArrowUpRight size={16} /></button></td></tr>) : employees.slice(0, 4).map(e => <tr key={e.id}><td><PersonCell person={e} subtitle={e.role} /></td><td><span className="department-tag">{e.department}</span></td><td><Badge status={e.status} /></td><td><button className="icon-button" aria-label={`View ${e.name}`} onClick={() => setModal({ type: 'employee-detail', item: e })}><ArrowUpRight size={16} /></button></td></tr>)}</tbody></table></div><div className="table-bottom-note"><span>{tab === 'Finance' ? `${data.invoices.length} invoices in your workspace` : `${employees.length} people. One shared direction.`}</span><span className="mini-avatars">{employees.slice(4, 8).map(e => <Avatar key={e.id} person={e} small />)}</span></div></section>
      <section className="panel activity-panel"><PanelHeading title="Workspace activity" subtitle="The latest, all in one place."><Activity size={17} className="subtle" /></PanelHeading><div className="timeline">{data.activity.slice(0, 3).map((a, i) => <div className="timeline-item" key={a.id}><span className={`timeline-icon ${i === 0 ? 'green' : i === 1 ? 'purple' : 'peach'}`}>{a.kind === 'people' ? <UserPlus size={16} /> : a.kind === 'payroll' ? <Wallet size={16} /> : <FileCheck2 size={16} />}</span><div><strong>{a.title}</strong><p>{a.detail}</p></div></div>)}</div><div className="workspace-note"><ShieldCheck size={19} /><p>Everything in its right place.<br /><span>Your workspace is up to date.</span></p></div></section></div>
  </>;
}

function Employees({ data, setModal, notify }) {
  const [search, setSearch] = useState(''); const [department, setDepartment] = useState('All departments'); const [status, setStatus] = useState('All employees'); const [view, setView] = useState('list');
  const rows = data.employees.filter(e => `${e.name} ${e.email} ${e.role}`.toLowerCase().includes(search.toLowerCase()) && (department === 'All departments' || e.department === department) && (status === 'All employees' || e.status === status));
  return <><PageTitle eyebrow="HUMAN RESOURCES" title="Good people. Great potential." description="A home for everyone who makes your business happen."><Button onClick={() => { exportCsv('employees.csv', rows); notify(rows.length ? 'Employee directory exported' : 'No matching employees to export'); }}><Download size={16} />Export</Button><Button variant="primary" onClick={() => setModal({ type: 'employee-form' })}><UserPlus size={17} />Add employee</Button></PageTitle><div className="summary-strip"><div><span className="summary-icon green"><Users size={20} /></span><div><strong>{data.employees.length}</strong><span>Total employees</span></div></div><div><span className="summary-icon purple"><BriefcaseBusiness size={20} /></span><div><strong>{data.employees.filter(e => e.status === 'Active').length}</strong><span>Active employees</span></div></div><div><span className="summary-icon peach"><CalendarDays size={20} /></span><div><strong>{data.employees.filter(e => e.status === 'On leave').length}</strong><span>On leave</span></div></div><div><span className="summary-icon blue"><Building2 size={20} /></span><div><strong>{departments.length}</strong><span>Departments</span></div></div></div><section className="panel"><div className="table-toolbar"><div className="tabs compact">{['All employees', 'Active', 'On leave', 'Inactive'].map(s => <button key={s} className={status === s ? 'selected' : ''} onClick={() => setStatus(s)}>{s}</button>)}</div><div className="view-toggle"><button aria-label="List view" className={view === 'list' ? 'selected' : ''} onClick={() => setView('list')}><List size={17} /></button><button aria-label="Grid view" className={view === 'grid' ? 'selected' : ''} onClick={() => setView('grid')}><LayoutGrid size={17} /></button></div></div><div className="filter-bar"><SearchField value={search} onChange={setSearch} placeholder="Search employees..." /><select aria-label="Filter department" value={department} onChange={e => setDepartment(e.target.value)}><option>All departments</option>{departments.map(d => <option key={d}>{d}</option>)}</select><span className="results-count">{rows.length} employees</span></div>{rows.length === 0 ? <Empty /> : view === 'list' ? <div className="table-wrap"><table><thead><tr><th>EMPLOYEE</th><th>DEPARTMENT</th><th>EMPLOYMENT</th><th>STATUS</th><th>JOINED</th><th /></tr></thead><tbody>{rows.map(e => <tr key={e.id}><td><PersonCell person={e} subtitle={e.role} /></td><td>{e.department}</td><td>{e.employment}</td><td><Badge status={e.status} /></td><td>{dateLabel(e.joined)}</td><td><button className="icon-button" aria-label={`View ${e.name}`} onClick={() => setModal({ type: 'employee-detail', item: e })}><ArrowUpRight size={17} /></button></td></tr>)}</tbody></table></div> : <div className="employee-grid">{rows.map(e => <button className="employee-card" key={e.id} onClick={() => setModal({ type: 'employee-detail', item: e })}><Avatar person={e} /><strong>{e.name}</strong><span>{e.role}</span><span className="department-tag">{e.department}</span><Badge status={e.status} /></button>)}</div>}<div className="table-footer">Showing {rows.length} of {data.employees.length} employees<span>People first, always.</span></div></section></>;
}
function SearchField({ value, onChange, placeholder }) { return <label className="search-field"><Search size={17} /><input aria-label={placeholder} value={value} onChange={e => onChange(e.target.value)} placeholder={placeholder} />{value && <button type="button" aria-label="Clear search" onClick={() => onChange('')}><X size={14} /></button>}</label>; }
function Attendance({ data, update, notify }) {
  const [search, setSearch] = useState(''); const [status, setStatus] = useState('All statuses');
  const active = data.employees.filter(e => e.status !== 'Inactive');
  const rows = active.filter(e => e.name.toLowerCase().includes(search.toLowerCase()) && (status === 'All statuses' || (data.attendance[e.id]?.status || 'Absent') === status));
  return <><PageTitle eyebrow="HUMAN RESOURCES" title="Every day counts." description="A simple, shared view of your team's working day."><Button onClick={() => { exportCsv('attendance.csv', rows.map(e => ({ employee: e.name, department: e.department, date: new Date().toISOString().slice(0, 10), ...data.attendance[e.id] }))); notify(rows.length ? 'Attendance report exported' : 'No attendance records to export'); }}><Download size={16} />Export attendance</Button></PageTitle><div className="metrics-grid">{[{ label: 'Present', icon: Users }, { label: 'Late', icon: Clock3 }, { label: 'On leave', icon: CalendarDays }, { label: 'Absent', icon: BriefcaseBusiness }].map(s => <Metric key={s.label} label={s.label} value={active.filter(e => (data.attendance[e.id]?.status || 'Absent') === s.label).length} icon={s.icon} note={<span>{new Date().toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'})}</span>} />)}</div><section className="panel"><PanelHeading title="Daily attendance" subtitle="Thursday, {new Date().toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'})} · Demo workday"><span className="badge neutral">09:00 – 18:00</span></PanelHeading><div className="filter-bar"><SearchField value={search} onChange={setSearch} placeholder="Find a team member..." /><select aria-label="Attendance status" value={status} onChange={e => setStatus(e.target.value)}>{['All statuses', 'Present', 'Late', 'On leave', 'Absent'].map(s => <option key={s}>{s}</option>)}</select></div><div className="table-wrap"><table><thead><tr><th>EMPLOYEE</th><th>DEPARTMENT</th><th>CHECK-IN</th><th>STATUS</th><th>UPDATE ATTENDANCE</th></tr></thead><tbody>{rows.map(e => { const a = data.attendance[e.id] || { status: 'Absent', checkIn: '' }; return <tr key={e.id}><td><PersonCell person={e} /></td><td>{e.department}</td><td className="tabular">{a.checkIn || '—'}</td><td><Badge status={a.status} /></td><td><select aria-label={`Attendance for ${e.name}`} className="compact-select" value={a.status} onChange={event => { const next = event.target.value; update(d => ({ ...d, attendance: { ...d.attendance, [e.id]: { status: next, checkIn: ['Present', 'Late'].includes(next) ? a.checkIn || '09:00' : '' } } }), `Attendance updated for ${e.name}`, 'people'); }}>{['Present', 'Late', 'On leave', 'Absent'].map(s => <option key={s}>{s}</option>)}</select></td></tr>; })}</tbody></table>{!rows.length && <Empty />}</div></section></>;
}
function Leave({ data, setModal, update }) {
  const [filter, setFilter] = useState('All requests');
  const rows = data.leaves.filter(l => filter === 'All requests' || l.status === filter);
  return <><PageTitle eyebrow="HUMAN RESOURCES" title="Room to recharge." description="Manage time off and keep your team in the loop."><Button variant="primary" onClick={() => setModal({ type: 'leave-form' })}><Plus size={17} />New leave request</Button></PageTitle><div className="info-banner"><CalendarDays size={21} /><div><strong>A little planning goes a long way.</strong><p>{data.leaves.filter(l => l.status === 'Pending').length} requests are waiting for review. Approve or decline them below.</p></div></div><section className="panel"><div className="table-toolbar"><div className="tabs">{['All requests', 'Pending', 'Approved', 'Rejected'].map(s => <button key={s} className={filter === s ? 'selected' : ''} onClick={() => setFilter(s)}>{s}{s === 'Pending' && <span className="tab-count">{data.leaves.filter(l => l.status === s).length}</span>}</button>)}</div></div><div className="table-wrap"><table><thead><tr><th>EMPLOYEE</th><th>LEAVE TYPE</th><th>DATES</th><th>DAYS</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody>{rows.map(l => <tr key={l.id}><td><PersonCell person={data.employees.find(e => e.id === l.employeeId)} /></td><td>{l.type}</td><td><span>{dateLabel(l.start)}</span><small className="cell-subtitle">to {dateLabel(l.end)}</small></td><td>{daysBetween(l.start, l.end)}</td><td><Badge status={l.status} /></td><td><div className="row-actions">{l.status === 'Pending' && <button className="approve-button" onClick={() => update(d => ({ ...d, leaves: d.leaves.map(x => x.id === l.id ? { ...x, status: 'Approved' } : x) }), 'Leave request approved', 'people')} aria-label={`Approve ${l.id}`}><Check size={16} /></button>}<button className="icon-button" aria-label={`View ${l.id}`} onClick={() => setModal({ type: 'leave-detail', item: l })}><ArrowUpRight size={17} /></button></div></td></tr>)}</tbody></table>{!rows.length && <Empty title="No leave requests here" text="Records from the connected database will appear here." />}</div></section><p className="footnote">Leave duration uses calendar days. Approval records the decision; daily attendance is managed separately.</p></>;
}
function Payroll({ data, setModal, notify }) {
  const active = data.employees.filter(e => e.status !== 'Inactive');
  const rows = data.payroll?.employees || active.map(e => ({ id: e.id, name: e.name, department: e.department, salary: e.salary, color: e.color, role: e.role }));
  const total = data.payroll?.total ?? sum(active, 'salary');
  return <><PageTitle eyebrow="HUMAN RESOURCES" title="Good work deserves a good payday." description="Review and manage your team's monthly payroll."><Button onClick={() => { exportCsv('payroll.csv', rows.map(e => ({ employee: e.name, department: e.department, gross: e.salary, deductions: 0, net: e.salary, status: data.payroll?.status || 'Not processed' }))); notify(rows.length ? 'Payroll exported' : 'No employees to export'); }}><Download size={16} />Export payroll</Button><Button variant="primary" onClick={() => setModal({ type: 'payroll-run' })} disabled={data.payroll?.status === 'Paid'}><Wallet size={17} />{data.payroll?.status === 'Paid' ? 'Payroll completed' : data.payroll ? 'Review payroll' : 'Run payroll'}</Button></PageTitle><div className="payroll-hero"><div><span className="eyebrow">{new Date().toLocaleDateString('en-US',{month:'long',year:'numeric'}).toUpperCase()} PAYROLL</span><h2>{money(total)}<span>total gross pay</span></h2><p>{rows.length} employees · Pay date {data.payroll?.payDate ? dateLabel(data.payroll.payDate) : 'not scheduled'}</p></div><div className="payroll-hero-status"><span className="payroll-hero-icon"><Wallet size={32} /></span><Badge status={data.payroll?.status || 'Draft'} /></div></div><div className="steps">{['Review employees', 'Generate payroll', 'Approve payroll', 'Record payment'].map((s, i) => { const step = !data.payroll ? 0 : data.payroll.status === 'Pending' ? 1 : data.payroll.status === 'Approved' ? 2 : 3; return <div className={i <= step ? 'done' : ''} key={s}><span>{i < step ? <Check size={15} /> : i + 1}</span>{s}</div>; })}</div><section className="panel"><PanelHeading title="Payroll breakdown" subtitle="Saved payroll snapshot; deductions are shown as recorded" /><div className="table-wrap"><table><thead><tr><th>EMPLOYEE</th><th>DEPARTMENT</th><th>BASE SALARY</th><th>DEDUCTIONS</th><th>NET PAY</th><th>STATUS</th></tr></thead><tbody>{rows.map(e => <tr key={e.id}><td><PersonCell person={e} subtitle={e.role} /></td><td>{e.department}</td><td>{money(e.salary)}</td><td>{money(0)}</td><td><strong>{money(e.salary)}</strong></td><td><Badge status={data.payroll?.status || 'Draft'} /></td></tr>)}</tbody><tfoot><tr><td colSpan="2">Total · {rows.length} employees</td><td>{money(total)}</td><td>{money(0)}</td><td>{money(total)}</td><td /></tr></tfoot></table></div></section><p className="footnote">Payroll figures come from employee and payroll records saved in the database.</p></>;
}
function Invoices({ data: allData, setModal, notify }) {
  const [currency, setCurrency] = useState('USD');
  const data = {...allData, invoices: allData.invoices.filter(i=>(i.currency||'USD')===currency)};
  const money = (n, compact=false) => new Intl.NumberFormat('en-US',{style:'currency',currency,maximumFractionDigits:compact?1:2,minimumFractionDigits:compact?0:2,...(compact?{notation:'compact'}:{})}).format(n);
  const [search, setSearch] = useState(''); const [filter, setFilter] = useState('All invoices');
  const rows = data.invoices.filter(i => (filter === 'All invoices' || i.status === filter) && `${i.client} ${i.id}`.toLowerCase().includes(search.toLowerCase()));
  return <><PageTitle eyebrow="FINANCE" title="From great work to paid work." description="Create invoices, track payments, and keep cash flowing."><Button onClick={() => { exportCsv('invoices.csv', rows); notify(rows.length ? 'Invoices exported' : 'No matching invoices to export'); }}><Download size={16} />Export</Button><Button variant="primary" onClick={() => setModal({ type: 'invoice-form' })}><Plus size={17} />Create invoice</Button></PageTitle><div className="mf-currency-switch"><label htmlFor="invoice-currency">Invoice currency</label><select id="invoice-currency" value={currency} onChange={e=>setCurrency(e.target.value)}><option value="USD">USD · Existing workspace</option><option value="LKR">LKR · Manufacturing</option></select><span>Currency totals are kept separate.</span></div><div className="metrics-grid"><Metric label="Total invoiced" value={money(sum(data.invoices.filter(i => i.status !== 'Draft')), true)} icon={FileText} note={<span>Excludes draft invoices</span>} /><Metric label="Collected" value={money(sum(data.invoices.filter(i => i.status === 'Paid')), true)} icon={CheckCheck} note={<span>Payments recorded</span>} /><Metric label="Outstanding" value={money(sum(data.invoices.filter(i => ['Pending', 'Overdue'].includes(i.status))), true)} icon={Clock3} note={<span>Awaiting payment</span>} /><Metric accent label="Overdue" value={money(sum(data.invoices.filter(i => i.status === 'Overdue')), true)} icon={Receipt} note={<span>Ready for a follow-up</span>} /></div><section className="panel"><div className="table-toolbar"><div className="tabs">{['All invoices', 'Pending', 'Paid', 'Overdue', 'Draft'].map(s => <button key={s} className={filter === s ? 'selected' : ''} onClick={() => setFilter(s)}>{s}</button>)}</div></div><div className="filter-bar"><SearchField value={search} onChange={setSearch} placeholder="Search clients or invoice numbers..." /><span className="results-count">{rows.length} invoices</span></div><div className="table-wrap"><table><thead><tr><th>INVOICE</th><th>CLIENT</th><th>AMOUNT</th><th>DUE DATE</th><th>STATUS</th><th /></tr></thead><tbody>{rows.map((i, n) => <tr key={i.id}><td><button className="table-link" onClick={() => setModal({ type: 'invoice-detail', item: i })}>{i.id}</button><small className="cell-subtitle">{dateLabel(i.issued)}</small></td><td><div className="client-cell"><span className={`client-logo ${colors[n % colors.length]}`}>{i.client[0]}</span>{i.client}</div></td><td><strong>{money(i.amount)}</strong></td><td>{dateLabel(i.due)}</td><td><Badge status={i.status} /></td><td><button className="icon-button" aria-label={`Open ${i.id}`} onClick={() => setModal({ type: 'invoice-detail', item: i })}><ArrowUpRight size={17} /></button></td></tr>)}</tbody></table>{!rows.length && <Empty />}</div><div className="table-footer">Showing {rows.length} invoices<span>All amounts in {currency}</span></div></section></>;
}
function Expenses({ data, setModal, notify }) {
  const [filter, setFilter] = useState('All expenses'); const [search, setSearch] = useState('');
  const rows = data.expenses.filter(e => (filter === 'All expenses' || e.status === filter) && `${e.description} ${e.category} ${data.employees.find(p => p.id === e.employeeId)?.name}`.toLowerCase().includes(search.toLowerCase()));
  return <><PageTitle eyebrow="FINANCE" title="Every expense, accounted for." description="Keep spending visible and reimbursements moving."><Button onClick={() => { exportCsv('expenses.csv', rows.map(e => ({ ...e, employee: data.employees.find(p => p.id === e.employeeId)?.name }))); notify(rows.length ? 'Expenses exported' : 'No matching expenses to export'); }}><Download size={16} />Export</Button><Button variant="primary" onClick={() => setModal({ type: 'expense-form' })}><Plus size={17} />Add expense</Button></PageTitle><div className="summary-strip"><div><span className="summary-icon green"><Receipt size={21} /></span><div><strong>{money(sum(data.expenses.filter(e => e.status !== 'Rejected')))}</strong><span>Total claims</span></div></div><div><span className="summary-icon peach"><Clock3 size={21} /></span><div><strong>{money(sum(data.expenses.filter(e => e.status === 'Pending')))}</strong><span>Pending approval</span></div></div><div><span className="summary-icon purple"><CheckCheck size={21} /></span><div><strong>{money(sum(data.expenses.filter(e => e.status === 'Approved')))}</strong><span>Ready to reimburse</span></div></div><div><span className="summary-icon blue"><Wallet size={21} /></span><div><strong>{money(sum(data.expenses.filter(e => e.status === 'Paid')))}</strong><span>Reimbursed</span></div></div></div><section className="panel"><div className="table-toolbar"><div className="tabs">{['All expenses', 'Pending', 'Approved', 'Paid', 'Rejected'].map(s => <button key={s} className={filter === s ? 'selected' : ''} onClick={() => setFilter(s)}>{s}</button>)}</div></div><div className="filter-bar"><SearchField value={search} onChange={setSearch} placeholder="Search expenses..." /><span className="results-count">{rows.length} expenses</span></div><div className="table-wrap"><table><thead><tr><th>EXPENSE</th><th>EMPLOYEE</th><th>CATEGORY</th><th>AMOUNT</th><th>STATUS</th><th /></tr></thead><tbody>{rows.map(e => <tr key={e.id}><td><strong>{e.description}</strong><small className="cell-subtitle">{dateLabel(e.date)} · {e.id}</small></td><td><PersonCell person={data.employees.find(p => p.id === e.employeeId)} subtitle="Expense claimant" /></td><td><span className="department-tag">{e.category}</span></td><td><strong>{money(e.amount)}</strong></td><td><Badge status={e.status} /></td><td><button className="icon-button" aria-label={`Review ${e.id}`} onClick={() => setModal({ type: 'expense-detail', item: e })}><ArrowUpRight size={17} /></button></td></tr>)}</tbody></table>{!rows.length && <Empty />}</div></section></>;
}
function Accounts({ data: allData, notify }) {
  const data = {...allData, invoices: allData.invoices.filter(i => (i.currency || 'USD') === 'USD')};
  const [filter, setFilter] = useState('All transactions');
  const incoming = data.invoices.filter(i => i.status === 'Paid').map(i => ({ id: i.id, description: `Payment from ${i.client}`, category: 'Client payment', date: i.paidDate || i.issued, amount: Number(i.amount) || 0, type: 'Income' }));
  const outgoing = data.expenses.filter(e => e.status === 'Paid').map(e => ({ id: e.id, description: e.description, category: e.category, date: e.paidDate || e.date, amount: -(Number(e.amount) || 0), type: 'Expense' }));
  const payroll = data.payroll?.status === 'Paid' ? [{ id: `PAY-${data.payroll.month || 'current'}`, description: 'Payroll payment', category: 'Payroll', date: data.payroll.paidDate || data.payroll.month || '', amount: -(Number(data.payroll.total) || 0), type: 'Expense' }] : [];
  const all = [...incoming, ...outgoing, ...payroll].sort((a, b) => (b.date || '').localeCompare(a.date || ''));
  const rows = all.filter(t => filter === 'All transactions' || t.type === filter);
  const cashPosition = all.reduce((total, row) => total + row.amount, 0);
  return <><PageTitle eyebrow="FINANCE" title="Your recorded cash movement." description="Balances are calculated from paid records in your connected workspace."><Button onClick={() => { exportCsv('account-transactions.csv', rows); notify(rows.length ? 'Transactions exported' : 'No transactions to export'); }}><Download size={16} />Export statement</Button></PageTitle><div className="account-layout"><div className="bank-card"><div><span className="bank-brand"><Building2 size={20} />Orbit Business</span><span>RECORDED CASH POSITION</span></div><p>Net recorded movement</p><h2>{money(cashPosition)}</h2><div className="bank-card-footer"><span>Based on paid invoices and outflows</span><span>USD</span></div><div className="bank-rings" /></div><div className="account-summary panel"><PanelHeading title="Account movement" subtitle="Calculated from records marked paid" /><div><span><i className="income-dot" />Money in</span><strong className="positive-text">+{money(incoming.reduce((n, t) => n + t.amount, 0))}</strong></div><div><span><i className="expense-dot" />Money out</span><strong>{money(-outgoing.concat(payroll).reduce((n, t) => n + t.amount, 0))}</strong></div><p><ShieldCheck size={16} />No external bank connection</p></div></div><div className="info-banner"><Wallet size={20}/><div><strong>Recorded balance only</strong><p>This total comes from paid invoices and recorded expenses or payroll. It is not a live bank balance.</p></div></div><section className="panel"><PanelHeading title="Recorded transactions" subtitle="Payments recorded in invoices, expenses, and payroll." /><div className="table-toolbar"><div className="tabs">{['All transactions', 'Income', 'Expense'].map(s => <button key={s} className={filter === s ? 'selected' : ''} onClick={() => setFilter(s)}>{s}</button>)}</div></div><div className="table-wrap"><table><thead><tr><th>TRANSACTION</th><th>REFERENCE</th><th>DATE</th><th>CATEGORY</th><th>AMOUNT</th></tr></thead><tbody>{rows.map(t => <tr key={t.id}><td><div className="transaction-cell"><span className={`transaction-icon ${t.amount > 0 ? 'green' : 'peach'}`}>{t.amount > 0 ? <ArrowDownLeft size={18} /> : <ArrowUpRight size={18} />}</span><strong>{t.description}</strong></div></td><td>{t.id}</td><td>{t.date ? dateLabel(t.date) : '?'}</td><td>{t.category}</td><td className={t.amount > 0 ? 'positive-text' : ''}><strong>{t.amount > 0 ? '+' : '?'}{money(Math.abs(t.amount))}</strong></td></tr>)}</tbody></table>{!rows.length && <Empty title="No recorded transactions" text="Paid invoices and outflows will appear here." />}</div></section></>;
}
function Reports({ data: allData, notify }) {
  const data = {...allData, invoices: allData.invoices.filter(i=>(i.currency||'USD')==='USD')};
  const [report, setReport] = useState('Financial summary');
  const [month, setMonth] = useState(() => new Date().toISOString().slice(0,7));
  const invoices = data.invoices.filter(i => (i.issued||'').startsWith(month)); const expenses = data.expenses.filter(e => (e.date||'').startsWith(month));
  const income = sum(data.invoices.filter(i => i.status === 'Paid' && (i.paidDate || i.issued || '').startsWith(month))); const expense = sum(data.expenses.filter(e => e.status === 'Paid' && (e.paidDate || e.date || '').startsWith(month)));
  const payroll = data.payroll?.status === 'Paid' && (data.payroll.month || data.payroll.paidDate || '').startsWith(month) ? data.payroll.total : 0;
  const rows = report === 'Financial summary' ? [{ metric: 'Collected invoice payments', amount: income }, { metric: 'Reimbursed expenses', amount: expense }, { metric: 'Payroll payments', amount: payroll }, { metric: 'Net recorded cash movement', amount: income - expense - payroll }, { metric: 'Outstanding invoices', amount: sum(invoices.filter(i => ['Pending', 'Overdue'].includes(i.status))) }] : report === 'Employee directory' ? data.employees.filter(e => (e.joined || '').slice(0, 7) <= month).map(e => ({ employee: e.name, department: e.department, status: e.status, salary: e.salary })) : report === 'Expense breakdown' ? ['Equipment', 'Travel', 'Office', 'Software', 'Meals', 'Other'].map(c => ({ category: c, total_claimed: sum(expenses.filter(e => e.category === c && e.status !== 'Rejected')), reimbursed: sum(expenses.filter(e => e.category === c && e.status === 'Paid')) })) : data.leaves.filter(l => (l.start || '').startsWith(month)).map(l => ({ employee: data.employees.find(e => e.id === l.employeeId)?.name, type: l.type, days: daysBetween(l.start, l.end), status: l.status }));
  return <><PageTitle eyebrow="INSIGHTS & REPORTING" title="See the bigger picture." description="Turn everyday activity into a clearer understanding of your business."><Button variant="primary" onClick={() => { exportCsv(`orbit-${report.toLowerCase().replaceAll(' ', '-')}-${month}.csv`, rows); notify(rows.length ? 'Report downloaded as CSV' : 'No records for this period'); }}><Download size={16} />Download report</Button></PageTitle><div className="report-options">{[{ name: 'Financial summary', icon: TrendingUp, description: 'Cash in, cash out, and what’s ahead.' }, { name: 'Employee directory', icon: Users, description: 'A closer look at your people.' }, { name: 'Expense breakdown', icon: Receipt, description: 'Understand where money goes.' }, { name: 'Leave summary', icon: CalendarDays, description: 'Time away, thoughtfully managed.' }].map(({ name, icon: Icon, description }) => <button className={`report-card ${report === name ? 'selected' : ''}`} key={name} onClick={() => setReport(name)}><Icon size={22} /><strong>{name}</strong><p>{description}</p>{report === name && <Check size={17} className="report-selected" />}</button>)}</div><section className="panel"><PanelHeading title={report} subtitle={report === 'Employee directory' ? 'Employees joined by the selected month · Current status and salary' : 'Financial summary uses payment dates; other reports use expense or leave dates'}><input type="month" aria-label="Report month" value={month} min="2023-01" max="2035-12" onChange={e => { if (e.target.value) setMonth(e.target.value); }} /></PanelHeading><div className="table-wrap">{rows.length ? <table><thead><tr>{Object.keys(rows[0]).map(k => <th key={k}>{k.replaceAll('_', ' ').toUpperCase()}</th>)}</tr></thead><tbody>{rows.map((r, i) => <tr key={i}>{Object.entries(r).map(([k, v]) => <td key={k}>{k === 'status' ? <Badge status={v} /> : ['amount', 'salary', 'total_claimed', 'reimbursed'].includes(k) ? <strong>{money(v)}</strong> : v}</td>)}</tr>)}</tbody></table> : <Empty title="No records for this month" text="Add records to populate this report." />}</div><div className="table-footer"><span>{rows.length} report rows · USD</span><span>Ready to export as CSV</span></div></section><div className="info-banner"><CircleHelp size={20} /><div><strong>Make the numbers your own.</strong><p>Reports reflect records loaded from the connected database.</p></div></div></>;
}
function SettingsPage({ data, update }) {
  const [saved, setSaved] = useState(false);
  return <><PageTitle eyebrow="WORKSPACE" title="Make yourself at home." description="The small details that make this workspace yours." /><section className="panel settings-panel"><PanelHeading title="Workspace details" subtitle="These workspace details are shared through the connected database." /><form onSubmit={e => { e.preventDefault(); const f = new FormData(e.currentTarget); update(d => ({ ...d, settings: { ...d.settings, company: f.get('company').trim(), admin: f.get('admin').trim(), email: f.get('email').trim(), weekStart: f.get('weekStart') } }), 'Workspace settings saved'); setSaved(true); }}><div className="form-grid"><Field label="Company name" name="company" defaultValue={data.settings.company} required maxLength={60} /><Field label="Administrator name" name="admin" defaultValue={data.settings.admin || ''} required maxLength={60} /><Field label="Email address" name="email" type="email" defaultValue={data.settings.email} required /><label className="field">Week starts on<select aria-label="Week starts on" name="weekStart" defaultValue={data.settings.weekStart}><option>Monday</option><option>Sunday</option></select></label><label className="field">Reporting currency<input value="USD — US Dollar" disabled /><small>Each record retains its saved currency.</small></label><label className="field">Workspace type<input value="Database-backed workspace" disabled /><small>Changes sync to the connected database.</small></label></div><div className="form-footer">{saved && <span className="positive-text">Your preferences are saved.</span>}<Button variant="primary" type="submit"><Check size={16} />Save changes</Button></div></form></section><div className="info-banner"><ShieldCheck size={20} /><div><strong>Database-backed workspace.</strong><p>Records are loaded from and saved to the connected ERP database. No bank transfers or emails are sent.</p></div></div></>;
}
function Field({ label, error, ...props }) { return <label className="field">{label}<input {...props} />{error && <small className="error-text">{error}</small>}</label>; }

function AppModal({ modal, onClose, data, update, notify, navigate, setModal, globalSearch, setGlobalSearch, openManufacturing, activeDepartment }) {
  const [error, setError] = useState('');
  const type = modal.type;
  const saveStatus = (collection, item, status, message) => { update(d => ({ ...d, [collection]: d[collection].map(x => x.id === item.id ? { ...x, status, ...(status === 'Paid' ? { paidDate: new Date().toISOString().slice(0,10) } : {}) } : x) }), message, collection === 'leaves' ? 'people' : 'finance'); onClose(); };
  const go = (id) => { onClose(); navigate(id); };
  if (type === 'quick') return <Modal title="What would you like to add?" subtitle="A small step to keep things moving." onClose={onClose}><div className="quick-actions">{[{ label: 'Add an employee', text: 'Welcome someone new to the team', icon: UserPlus, type: 'employee-form' }, { label: 'Create an invoice', text: 'Turn your work into a payment', icon: FileText, type: 'invoice-form' }, { label: 'Record an expense', text: 'Keep track of business spending', icon: Receipt, type: 'expense-form' }, { label: 'Request time off', text: 'Make space for a little recharge', icon: CalendarDays, type: 'leave-form' }].map(({ label, text, icon: Icon, type }) => <button key={type} onClick={() => setModal({ type })}><span className="summary-icon green"><Icon size={21} /></span><span><strong>{label}</strong><small>{text}</small></span><ArrowRight size={18} /></button>)}</div></Modal>;
  if (type === 'search') { const q = globalSearch.toLowerCase().trim(); const people = activeDepartment==='hr'&&q ? data.employees.filter(e => `${e.name} ${e.email} ${e.department}`.toLowerCase().includes(q)).slice(0, 5) : []; const invoices = activeDepartment==='finance'&&q ? data.invoices.filter(i => `${i.client} ${i.id}`.toLowerCase().includes(q)).slice(0, 3) : []; const matchingPages = pages.filter(p => departmentByPage(p.id)?.id===activeDepartment&&p.label.toLowerCase().includes(q)); const manufacturingMatches = activeDepartment==='manufacturing'&&q ? [...data.manufacturing.sheets.map(item=>({item,label:item.id,detail:item.material,page:'materials',type:'sheet'})),...data.manufacturing.jobs.map(item=>({item,label:item.id,detail:data.manufacturing.products.find(p=>p.id===item.productId)?.name,page:'production',type:'job-detail'})),...data.manufacturing.goods.map(item=>({item,label:item.id,detail:item.bin,page:'warehouse',type:'passport'})),...data.manufacturing.products.map(item=>({item,label:item.name,detail:item.id,page:'materials',type:'bom'}))].filter(r=>(r.label+' '+r.detail).toLowerCase().includes(q)).slice(0,8) : []; return <Modal title="Find your way around" onClose={onClose}><div className="modal-body"><SearchField value={globalSearch} onChange={setGlobalSearch} placeholder="Search this department..." /><div className="search-results">{matchingPages.map(p => <button key={p.id} onClick={() => go(p.id)}><p.icon size={18} /><span>{p.label}</span><ArrowUpRight size={15} /></button>)}{people.map(e => <button key={e.id} onClick={() => setModal({ type: 'employee-detail', item: e })}><Avatar person={e} small /><span>{e.name}<small>{e.department}</small></span><ArrowUpRight size={15} /></button>)}{invoices.map(i => <button key={i.id} onClick={() => setModal({ type: 'invoice-detail', item: i })}><FileText size={18} /><span>{i.client}<small>{i.id}</small></span><ArrowUpRight size={15} /></button>)}{manufacturingMatches.map(r=><button key={r.item.id} onClick={()=>openManufacturing(r.page,{type:r.type,item:r.item})}><BriefcaseBusiness size={18}/><span>{r.label}<small>{r.detail}</small></span><ArrowUpRight size={15}/></button>)}{!matchingPages.length && !people.length && !invoices.length && !manufacturingMatches.length && <Empty />}</div></div></Modal>; }
  if (type === 'help') return <Modal title="A quick hello to Orbit." subtitle="Your people and finances, comfortably in one place." onClose={onClose}><div className="modal-body guide"><div><span>01</span><p><strong>Start with your people.</strong>Add employees, update daily attendance, and review leave requests in Human Resources.</p></div><div><span>02</span><p><strong>Keep your money moving.</strong>Create invoices, record expenses, and review approvals in Finance. Recorded payments update Accounts.</p></div><div><span>03</span><p><strong>Make payday a good day.</strong>Generate payroll, approve the snapshot, then record the payment status. Export reports whenever you need.</p></div><div className="inline-note">Changes are saved to the connected database. Payment status is recorded; no bank integration is configured.</div><Button variant="primary" onClick={onClose}>Got it, let's explore<ArrowRight size={16} /></Button></div></Modal>;
  if (type === 'notifications') { const leaves = data.leaves.filter(l => l.status === 'Pending'); const expenses = data.expenses.filter(e => e.status === 'Pending'); return <Modal title="Your approval inbox" subtitle={`${leaves.length + expenses.length} items could use your attention.`} onClose={onClose}><div className="quick-actions"><button onClick={()=>openManufacturing('factory',{type:'alerts'})}><span className="summary-icon green"><BriefcaseBusiness size={20}/></span><span><strong>Manufacturing attention</strong><small>{manufacturingAlerts(data.manufacturing).length} material, production, and machine alerts</small></span><ArrowRight size={16}/></button>{leaves.map(l => <button key={l.id} onClick={() => setModal({ type: 'leave-detail', item: l })}><span className="summary-icon purple"><CalendarDays size={20} /></span><span><strong>{data.employees.find(e => e.id === l.employeeId)?.name}</strong><small>{l.type} · {daysBetween(l.start, l.end)} days</small></span><ArrowRight size={16} /></button>)}{expenses.map(e => <button key={e.id} onClick={() => setModal({ type: 'expense-detail', item: e })}><span className="summary-icon peach"><Receipt size={20} /></span><span><strong>{e.description}</strong><small>{money(e.amount)} · Expense approval</small></span><ArrowRight size={16} /></button>)}{!leaves.length && !expenses.length && <Empty title="All caught up!" text="There are no pending approvals." />}</div></Modal>; }
  if (type === 'employee-form') { const employee = modal.item; return <Modal title={employee ? 'Edit employee' : 'Meet your newest team member.'} subtitle={employee ? 'Keep their details up to date.' : 'A few details to get them settled in.'} onClose={onClose}><form onSubmit={e => { e.preventDefault(); const f = Object.fromEntries(new FormData(e.currentTarget)); if (!f.name.trim() || !f.role.trim()) return setError('Please enter a name and job title.'); if (data.employees.some(x => x.email.toLowerCase() === f.email.toLowerCase().trim() && x.id !== employee?.id)) return setError('An employee with this email already exists.'); const next = { ...employee, ...f, name: f.name.trim(), email: f.email.trim(), role: f.role.trim(), salary: Number(f.salary), id: employee?.id || `EMP-${crypto.randomUUID().slice(0, 8).toUpperCase()}`, status: employee?.status || 'Active', color: employee?.color || colors[data.employees.length % colors.length] }; update(d => ({ ...d, employees: employee ? d.employees.map(x => x.id === employee.id ? next : x) : [...d.employees, next] }), `${next.name} ${employee ? 'updated' : 'added to the team'}`, 'people'); onClose(); }}><div className="modal-body form-grid"><Field label="Full name" name="name" placeholder="e.g. Jamie Lee" defaultValue={employee?.name} required maxLength={80} /><Field label="Work email" name="email" type="email" placeholder="jamie@company.com" defaultValue={employee?.email} required /><Field label="Phone number" name="phone" type="tel" placeholder="e.g. +94 77 123 4567" defaultValue={employee?.phone || employee?.phoneNumber || employee?.mobile} /><label className="field">Job title<select aria-label="Job title" name="role" defaultValue={employee?.role || ROLES[0]} required>{[...new Set([...employeeJobTitles, ...(employee?.role ? [employee.role] : [])])].map(role => <option key={role} value={role}>{role}</option>)}</select></label><label className="field">Department<select aria-label="Department" name="department" defaultValue={employee?.department}>{departments.map(d => <option key={d}>{d}</option>)}</select></label><Field label="Territory" name="territory" placeholder="e.g. Kandy City" defaultValue={employee?.territory} /><Field label="Region / team" name="region" placeholder="e.g. Central Region" defaultValue={employee?.region || employee?.team} /><label className="field">Employment type<select aria-label="Employment type" name="employment" defaultValue={employee?.employment}>{['Full-time', 'Part-time', 'Contract'].map(t => <option key={t}>{t}</option>)}</select></label><Field label="Monthly salary (USD)" type="number" name="salary" min="0" max="1000000" step="0.01" defaultValue={employee?.salary} required /><Field label="Joining date" type="date" name="joined" defaultValue={employee?.joined || new Date().toISOString().slice(0, 10)} required />{error && <p className="form-error" role="alert">{error}</p>}</div><div className="modal-footer"><Button type="button" onClick={onClose}>Cancel</Button><Button type="submit" variant="primary">{employee ? 'Save changes' : 'Add employee'}<Check size={16} /></Button></div></form></Modal>; }
  if (type === 'employee-detail') { const e = data.employees.find(e => e.id === modal.item.id); return <Modal title="Employee profile" onClose={onClose}><div className="modal-body"><div className="profile-hero"><Avatar person={e} /><h2>{e.name}</h2><p>{e.role}</p><Badge status={e.status} /></div><dl className="detail-grid"><div><dt>Email</dt><dd>{e.email}</dd></div><div><dt>Department</dt><dd>{e.department}</dd></div><div><dt>Employee ID</dt><dd>{e.id}</dd></div><div><dt>Employment</dt><dd>{e.employment}</dd></div><div><dt>Joined</dt><dd>{dateLabel(e.joined)}</dd></div><div><dt>Monthly salary</dt><dd>{money(e.salary)}</dd></div></dl></div><div className="modal-footer"><Button variant={e.status === 'Inactive' ? 'secondary' : 'danger'} onClick={() => saveStatus('employees', e, e.status === 'Inactive' ? 'Active' : 'Inactive', `${e.name} ${e.status === 'Inactive' ? 'reactivated' : 'deactivated'}`)}>{e.status === 'Inactive' ? 'Reactivate' : 'Deactivate'}</Button><Button variant="primary" onClick={() => setModal({ type: 'employee-form', item: e })}>Edit employee<ArrowRight size={16} /></Button></div></Modal>; }
  if (type === 'leave-form') return <Modal title="A little time for yourself." subtitle="Submit a leave request for review." onClose={onClose}><form onSubmit={e => { e.preventDefault(); const f = Object.fromEntries(new FormData(e.currentTarget)); if (f.end < f.start) return setError('The end date must be on or after the start date.'); if (data.leaves.some(l => l.employeeId === f.employeeId && l.status !== 'Rejected' && l.start <= f.end && l.end >= f.start)) return setError('This employee already has a request overlapping these dates.'); update(d => ({ ...d, leaves: [{ ...f, id: `LV-${crypto.randomUUID().slice(0, 6)}`, status: 'Pending' }, ...d.leaves] }), 'Leave request submitted', 'people'); onClose(); }}><div className="modal-body form-grid"><EmployeeSelect data={data} /><label className="field">Leave type<select aria-label="Leave type" name="type"><option>Annual leave</option><option>Sick leave</option><option>Personal leave</option><option>Unpaid leave</option></select></label><Field label="Start date" name="start" type="date" defaultValue={new Date().toISOString().slice(0, 10)} required /><Field label="End date" name="end" type="date" defaultValue={new Date().toISOString().slice(0, 10)} required /><label className="field full">Reason<textarea name="reason" placeholder="A little context for the approver..." required maxLength={500} /></label>{error && <p className="form-error" role="alert">{error}</p>}</div><div className="modal-footer"><Button type="button" onClick={onClose}>Cancel</Button><Button variant="primary" type="submit">Submit request<ArrowRight size={16} /></Button></div></form></Modal>;
  if (type === 'leave-detail') { const l = data.leaves.find(x => x.id === modal.item.id); return <Modal title="Leave request" subtitle={l.id} onClose={onClose}><div className="modal-body"><PersonCell person={data.employees.find(e => e.id === l.employeeId)} /><dl className="detail-grid"><div><dt>Type</dt><dd>{l.type}</dd></div><div><dt>Status</dt><dd><Badge status={l.status} /></dd></div><div><dt>From</dt><dd>{dateLabel(l.start)}</dd></div><div><dt>To</dt><dd>{dateLabel(l.end)}</dd></div><div><dt>Duration</dt><dd>{daysBetween(l.start, l.end)} calendar days</dd></div></dl><div className="inline-note">{l.reason}</div></div><div className="modal-footer">{l.status === 'Pending' ? <><Button variant="danger" onClick={() => saveStatus('leaves', l, 'Rejected', 'Leave request declined')}>Decline</Button><Button variant="primary" onClick={() => saveStatus('leaves', l, 'Approved', 'Leave request approved')}><Check size={16} />Approve request</Button></> : <Button onClick={onClose}>Close</Button>}</div></Modal>; }
  if (type === 'invoice-form') return <Modal title="Let's make it official." subtitle="Create a new client invoice. All amounts are in USD." onClose={onClose}><form onSubmit={e => { e.preventDefault(); const f = Object.fromEntries(new FormData(e.currentTarget)); if (!f.client.trim() || !f.description.trim()) return setError('Please enter a client and description.'); if (f.due < f.issued) return setError('Due date cannot be before the invoice date.'); const next = { ...f, client: f.client.trim(), amount: Number(f.amount), id: `INV-2026-${crypto.randomUUID().slice(0, 6).toUpperCase()}`, status: f.status === 'Pending' && f.due < new Date().toISOString().slice(0,10) ? 'Overdue' : f.status }; update(d => ({ ...d, invoices: [next, ...d.invoices] }), `Invoice created for ${next.client}`); onClose(); }}><div className="modal-body form-grid"><Field label="Client name" name="client" required placeholder="e.g. Layers Studio" maxLength={80} /><Field label="Client email" name="email" type="email" required placeholder="billing@client.com" /><Field label="Invoice date" name="issued" type="date" defaultValue={new Date().toISOString().slice(0,10)} required /><Field label="Due date" name="due" type="date" defaultValue={new Date(Date.now()+14*86400000).toISOString().slice(0,10)} required /><Field label="Amount (USD)" name="amount" type="number" min="0.01" max="10000000" step="0.01" required placeholder="0.00" /><label className="field">Initial status<select aria-label="Initial status" name="status"><option>Draft</option><option>Pending</option></select></label><label className="field full">Description<textarea name="description" placeholder="What is this invoice for?" required maxLength={500} /></label>{error && <p className="form-error" role="alert">{error}</p>}</div><div className="modal-footer"><Button type="button" onClick={onClose}>Cancel</Button><Button type="submit" variant="primary">Create invoice<ArrowRight size={16} /></Button></div></form></Modal>;
  if (type === 'invoice-detail') { const i = data.invoices.find(x => x.id === modal.item.id); const money = n => new Intl.NumberFormat('en-US',{style:'currency',currency:i.currency||'USD',minimumFractionDigits:2,maximumFractionDigits:2}).format(n); return <Modal title="Invoice details" subtitle={i.id} onClose={onClose}><div className="modal-body"><div className="invoice-top"><div><span className="eyebrow">BILLED TO</span><h2>{i.client}</h2><p>{i.email}</p></div><Badge status={i.status} /></div><dl className="detail-grid"><div><dt>Issued</dt><dd>{dateLabel(i.issued)}</dd></div><div><dt>Due</dt><dd>{dateLabel(i.due)}</dd></div></dl><div className="invoice-line"><div><span>Description</span><strong>{i.description}</strong></div><strong>{money(i.amount)}</strong></div><div className="invoice-total"><span>Total due</span><strong>{money(i.amount)}</strong></div><p className="footnote">Demo invoice · No tax applied · No email is sent</p></div><div className="modal-footer"><Button onClick={() => { exportCsv(`${i.id}.csv`, [i]); notify('Invoice exported'); }}><Download size={16} />Download CSV</Button>{i.status === 'Draft' ? <Button variant="primary" onClick={() => saveStatus('invoices', i, i.due < new Date().toISOString().slice(0,10) ? 'Overdue' : 'Pending', 'Invoice finalized')}>Finalize invoice<Check size={16} /></Button> : i.status !== 'Paid' ? <Button variant="primary" onClick={() => saveStatus('invoices', i, 'Paid', `Payment recorded for ${i.client}`)}>Record payment<Check size={16} /></Button> : <Button onClick={onClose}>Close</Button>}</div></Modal>; }
  if (type === 'expense-form') return <Modal title="A place for every expense." subtitle="Record a business expense for approval." onClose={onClose}><form onSubmit={e => { e.preventDefault(); const f = Object.fromEntries(new FormData(e.currentTarget)); if (!f.description.trim()) return setError('Please describe the expense.'); update(d => ({ ...d, expenses: [{ ...f, amount: Number(f.amount), id: `EXP-${crypto.randomUUID().slice(0, 6).toUpperCase()}`, status: 'Pending' }, ...d.expenses] }), 'Expense submitted for approval'); onClose(); }}><div className="modal-body form-grid"><EmployeeSelect data={data} /><label className="field">Category<select aria-label="Category" name="category">{['Equipment', 'Travel', 'Office', 'Software', 'Meals', 'Other'].map(c => <option key={c}>{c}</option>)}</select></label><Field label="Amount (USD)" name="amount" type="number" min="0.01" max="1000000" step="0.01" required /><Field label="Expense date" name="date" type="date" defaultValue={new Date().toISOString().slice(0,10)} required /><label className="field full">Description<textarea name="description" placeholder="What was this expense for?" required maxLength={500} /></label>{error && <p className="form-error" role="alert">{error}</p>}</div><div className="modal-footer"><Button type="button" onClick={onClose}>Cancel</Button><Button variant="primary" type="submit">Submit expense<ArrowRight size={16} /></Button></div></form></Modal>;
  if (type === 'expense-detail') { const e = data.expenses.find(x => x.id === modal.item.id); return <Modal title="Expense details" subtitle={e.id} onClose={onClose}><div className="modal-body"><PersonCell person={data.employees.find(p => p.id === e.employeeId)} /><dl className="detail-grid"><div><dt>Category</dt><dd>{e.category}</dd></div><div><dt>Status</dt><dd><Badge status={e.status} /></dd></div><div><dt>Amount</dt><dd className="large-amount">{money(e.amount)}</dd></div><div><dt>Date</dt><dd>{dateLabel(e.date)}</dd></div></dl><div className="inline-note">{e.description}</div></div><div className="modal-footer">{e.status === 'Pending' ? <><Button variant="danger" onClick={() => saveStatus('expenses', e, 'Rejected', 'Expense declined')}>Decline</Button><Button variant="primary" onClick={() => saveStatus('expenses', e, 'Approved', 'Expense approved')}><Check size={16} />Approve expense</Button></> : e.status === 'Approved' ? <Button variant="primary" onClick={() => saveStatus('expenses', e, 'Paid', 'Expense reimbursement recorded')}><CheckCheck size={16} />Record reimbursement</Button> : <Button onClick={onClose}>Close</Button>}</div></Modal>; }
  if (type === 'payroll-run') { const active = data.employees.filter(e => e.status !== 'Inactive'); const payroll = data.payroll; const total = payroll?.total ?? sum(active, 'salary'); const status = payroll?.status; return <Modal title={status === 'Approved' ? 'Ready for payday.' : status === 'Pending' ? 'Review payroll.' : 'Let’s prepare payday.'} subtitle={`Payroll from saved employee records ? ${new Date().toLocaleDateString('en-US',{month:'long',year:'numeric'})}`} onClose={onClose}><div className="modal-body"><div className="payroll-preview"><Wallet size={30} /><span>Total payroll</span><strong>{money(total)}</strong><p>{payroll?.employees.length ?? active.length} employees · No deductions configured</p></div><div className="inline-note">{!status ? 'Generating payroll takes a snapshot of active employees and their current base salaries. Review this snapshot before approving.' : status === 'Pending' ? 'Review the payroll table before approving. Review the saved payroll snapshot before approval.' : 'This records the payroll payment status in the database. No bank integration is configured.'}</div></div><div className="modal-footer"><Button onClick={onClose}>Cancel</Button><Button variant="primary" disabled={!active.length && !payroll} onClick={() => { if (!payroll) update(d => ({ ...d, payroll: { status: 'Pending', total, employees: active.map(e => ({ id: e.id, name: e.name, department: e.department, salary: e.salary, role: e.role, color: e.color })) } }), 'Current payroll generated', 'payroll'); else update(d => ({ ...d, payroll: { ...d.payroll, status: status === 'Pending' ? 'Approved' : 'Paid', ...(status === 'Approved' ? { paidDate: new Date().toISOString().slice(0,10) } : {}) } }), status === 'Pending' ? 'Current payroll approved' : 'Current payroll payment recorded', 'payroll'); onClose(); }}> {status === 'Approved' ? 'Record payment' : status === 'Pending' ? 'Approve payroll' : 'Generate payroll'}<Check size={16} /></Button></div></Modal>; }
  return null;
}
function EmployeeSelect({ data }) { return <label className="field">Employee<select aria-label="Employee" name="employeeId" required defaultValue=""><option value="" disabled>Select an employee</option>{data.employees.filter(e => e.status !== 'Inactive').map(e => <option key={e.id} value={e.id}>{e.name}</option>)}</select></label>; }
